[asy]
unitsize(0.5 cm);

for (int i = 0; i <= 4; ++i) {
for (int j = 0; j <= 4; ++j) {
dot((i,j));
}}
draw((0,0)--(0,1)--(1,1)--(1,0)--cycle);
draw((0,1)--(0,2)--(1,2)--(1,1)--cycle);
